function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 8);
  const nums = Array.from({ length: n }, (_, i) => i);
  const swap = (a, b) => { const t = nums[a]; nums[a] = nums[b]; nums[b] = t; };
  const mode = rand();
  if (mode < 0.25) {
    for (let i = n - 1; i > 0; i--) swap(i, Math.floor(rand() * (i + 1)));
    return [nums];
  }
  // An ideal permutation: swap some disjoint neighbouring pairs.
  for (let i = 0; i + 1 < n; i++) {
    if (rand() < 0.4) {
      swap(i, i + 1);
      i++;
    }
  }
  // Sometimes break it with one swap two to four places apart.
  if (mode < 0.65 && n >= 3) {
    const i = Math.floor(rand() * (n - 2));
    const j = i + 2 + Math.floor(rand() * Math.min(3, n - i - 2));
    swap(i, j);
  }
  return [nums];
}
